layer.css:
[data-ryt="pitch"] { color: var(--ryt-accent); border-left: 3px solid rgb(255, 204, 0); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: italic; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 16px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-accent); border-top: 1px dashed rgb(214, 215, 219); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 4px; box-shadow: rgba(0, 0, 0, 0.06) 1px 3px 10px 0px; transition: transform 0.2s, box-shadow 0.2s; padding-bottom: 20px; position: relative }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-text); background-image: linear-gradient(rgba(255, 204, 0, 0.78), rgba(255, 204, 0, 0.78)); background-size: 100% 3.24px; background-position: 0px 100%; background-repeat: no-repeat; border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-size 0.2s }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 40px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.3; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); background-image: linear-gradient(rgba(255, 204, 0, 0.4), rgba(255, 204, 0, 0.4)); background-size: 0% 100%; background-position: 0px 0px; background-repeat: no-repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 21px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-size 0.22s }
[data-ryt="nav"] a { color: var(--ryt-accent); background-image: linear-gradient(rgba(255, 204, 0, 0.78), rgba(255, 204, 0, 0.78)); background-size: 0% 2.56px; background-position: 0px 100%; background-repeat: no-repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 600; font-style: normal; line-height: 1.8; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.18s, transform 0.18s, background-size 0.22s }
[data-ryt="button"] { color: var(--ryt-accent); background-color: var(--ryt-surface); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 50%; font-family: Arial; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.2s, border-color 0.2s, transform 0.2s }
[data-ryt="review"] { color: rgb(92, 96, 106); font-family: var(--ryt-font-heading); font-size: 15px; font-weight: 400; font-style: normal; line-height: 1.55; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(92, 96, 106); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
body { background-image: radial-gradient(rgb(214, 215, 219) 1.1px, rgba(0, 0, 0, 0) 1.1px); background-size: 24px 24px; background-position: 0px 12px; background-repeat: repeat }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 700; font-style: normal; line-height: 1.3; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-size 0.25s }
[data-ryt="button"]:hover { color: #1c1e22; transform: translateY(-2px) }
[data-ryt="nav"] a:hover { color: #1c1e22; transform: translateX(2px) }
article[data-ryt="rec-card"]::after { content: ""; display: block; position: absolute; color: var(--ryt-text); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-bottom: 20px solid var(--ryt-bg); border-left: 20px solid rgba(0, 0, 0, 0); border-radius: 0px 0px 4px; box-shadow: rgba(0, 0, 0, 0.05) -2px -2px 4px 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text); bottom: 0px; right: 0px }
article[data-ryt="rec-card"]:hover { transform: translateY(-3px); box-shadow: rgba(0, 0, 0, 0.12) 2px 9px 22px }
